import { render } from '@testing-library/react';
import { Provider } from 'react-redux';
import { configureStore } from '@reduxjs/toolkit';
import { MemoryRouter } from 'react-router-dom';

// Import your slices
import usersReducer from './features/users/usersSlice';
import postsReducer from './features/posts/postsSlice';

// Create a configured test store
function createTestStore(preloadedState = {}) {
  return configureStore({
    reducer: {
      users: usersReducer,
      posts: postsReducer
    },
    preloadedState: {
      users: { entities: {}, ids: [], loading: false, error: null },
      posts: { entities: {}, ids: [], loading: false, error: null },
      ...preloadedState
    }
  });
}

// Custom render function with providers
function renderWithProviders(
  ui,
  {
    preloadedState = {},
    store = createTestStore(preloadedState),
    ...renderOptions
  } = {}
) {
  function Wrapper({ children }) {
    return (
      <Provider store={store}>
        <MemoryRouter>{children}</MemoryRouter>
      </Provider>
    );
  }
  return { store, ...render(ui, { wrapper: Wrapper, ...renderOptions }) };
}

export { createTestStore, renderWithProviders };

import { screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { renderWithProviders } from './test-utils';
import UserList from './UserList';
import { userAdded, userDeleted } from './features/users/usersSlice';

describe('UserList component', () => {
  it('renders list of users', () => {
    const preloadedState = {
      users: {
        entities: {
          '1': { id: '1', name: 'Alice', email: 'alice@example.com' },
          '2': { id: '2', name: 'Bob', email: 'bob@example.com' }
        },
        ids: ['1', '2'],
        loading: false,
        error: null
      }
    };

    renderWithProviders(<UserList />, { preloadedState });

    expect(screen.getByText('Alice')).toBeInTheDocument();
    expect(screen.getByText('Bob')).toBeInTheDocument();
    expect(screen.getAllByRole('listitem')).toHaveLength(2);
  });

  it('dispatches deleteUser when delete button is clicked', async () => {
    const { store } = renderWithProviders(<UserList />, {
      preloadedState: {
        users: {
          entities: { '1': { id: '1', name: 'Alice', email: 'alice@example.com' } },
          ids: ['1'],
          loading: false,
          error: null
        }
      }
    });

    const deleteButton = screen.getByRole('button', { name: /delete/i });
    await userEvent.click(deleteButton);

    // Verify the action was dispatched
    const actions = store.getState().users;
    expect(actions.ids).not.toContain('1');
  });

  it('shows loading state', () => {
    renderWithProviders(<UserList />, {
      preloadedState: {
        users: { entities: {}, ids: [], loading: true, error: null }
      }
    });

    expect(screen.getByText(/loading/i)).toBeInTheDocument();
  });

  it('shows error message', () => {
    renderWithProviders(<UserList />, {
      preloadedState: {
        users: { entities: {}, ids: [], loading: false, error: 'Failed to load' }
      }
    });

    expect(screen.getByText(/failed to load/i)).toBeInTheDocument();
  });
});

import { screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { renderWithProviders } from './test-utils';
import AddUserForm from './AddUserForm';

describe('AddUserForm component', () => {
  it('submits form data correctly', async () => {
    const { store } = renderWithProviders(<AddUserForm />);

    // Fill in the form fields
    await userEvent.type(screen.getByLabelText(/name/i), 'Alice');
    await userEvent.type(screen.getByLabelText(/email/i), 'alice@example.com');

    // Submit the form
    await userEvent.click(screen.getByRole('button', { name: /submit/i }));

    // Verify dispatch or navigation happened
    const actions = store.getActions();
    expect(actions.some(action => 
      action.type === 'users/userAdded' || 
      action.type === 'users/addUser/pending'
    )).toBe(true);
  });

  it('validates required fields', async () => {
    renderWithProviders(<AddUserForm />);

    // Try to submit empty form
    await userEvent.click(screen.getByRole('button', { name: /submit/i }));

    // Form should show validation error
    expect(screen.getByText(/name is required/i)).toBeInTheDocument();
  });

  it('handles keyboard input', async () => {
    renderWithProviders(<AddUserForm />);

    const nameInput = screen.getByLabelText(/name/i);
    await userEvent.type(nameInput, 'Alice{backspace}{backspace}Bob');

    expect(nameInput).toHaveValue('Bob');
  });
});

import { renderHook } from '@testing-library/react';
import { Provider } from 'react-redux';
import { createTestStore } from './test-utils';
import { useSelector } from 'react-redux';
import { selectUserById, selectAllUsers } from './usersSlice';

describe('users selectors', () => {
  const setup = (preloadedState) => {
    const store = createTestStore(preloadedState);
    return renderHook(() => ({
      store,
      result: useSelector((state) => state)
    }));
  };

  it('selectAllUsers returns all users', () => {
    const { store } = setup({
      users: {
        entities: {
          '1': { id: '1', name: 'Alice' },
          '2': { id: '2', name: 'Bob' }
        },
        ids: ['1', '2'],
        loading: false,
        error: null
      }
    });

    const allUsers = selectAllUsers(store.getState());
    expect(allUsers).toHaveLength(2);
    expect(allUsers[0].name).toBe('Alice');
  });

  it('selectUserById returns specific user', () => {
    const { store } = setup({
      users: {
        entities: { '1': { id: '1', name: 'Alice' } },
        ids: ['1'],
        loading: false,
        error: null
      }
    });

    const user = selectUserById(store.getState(), '1');
    expect(user?.name).toBe('Alice');
  });
});
